"""Source-gated Native device-site construction and original-history measurement.

A site inventory is captured by a local operator from the selected map. No map or
blueprint claim is inferred from the frozen catalog or a synthetic fixture.
"""
from __future__ import annotations

import hashlib
import json
import math
from pathlib import Path

VALID_DEVICES = {"signal", "stop_sign", "other_control_device"}
VALID_DIRECTIONS = {"stop", "proceed", "none"}


def read_site(path: Path, expected_sha256: str, *, allow_diagnostic: bool = False) -> dict:
    raw = path.read_bytes()
    if hashlib.sha256(raw).hexdigest() != expected_sha256:
        raise ValueError("original Native site hash mismatch")
    site = json.loads(raw)
    if site.get("source_kind") != "original_local_native_site_inventory":
        raise ValueError("unverified Native site inventory")
    if site.get("diagnostic_fixture") and not allow_diagnostic:
        raise ValueError("diagnostic fixture cannot be an original Native site")
    for key in ("map_name", "jurisdiction_source", "governed_approach", "stop_line", "vehicle_route", "device_id", "device_type", "device_authority_source", "vehicle_applicability_source", "bike_blueprint_id", "participant_class", "classification_source"):
        if not site.get(key):
            raise ValueError("missing Native site field: " + key)
    if site["participant_class"] != "human_powered_bicycle":
        raise ValueError("selected witness requires a human-powered bicycle")
    if site["device_type"] not in VALID_DEVICES:
        raise ValueError("unsupported official device type")
    if len(site["vehicle_route"]) < 2 or len(site["stop_line"]) != 2:
        raise ValueError("incomplete route or stop line")
    try:
        route = [[float(v) for v in point] for point in site["vehicle_route"]]
        line = [[float(v) for v in point] for point in site["stop_line"]]
        if any(len(point) != 3 for point in route) or any(len(point) != 2 for point in line):
            raise ValueError("invalid original route or stop-line dimensions")
        if not all(math.isfinite(v) for point in route + line for v in point):
            raise ValueError("nonfinite original route or stop line")
        if math.dist(line[0], line[1]) < 0.1:
            raise ValueError("degenerate original stop line")
        if math.dist(route[0][:2], route[1][:2]) < 1.0:
            raise ValueError("degenerate original route")
        x0, y0 = line[0]
        x1, y1 = line[1]
        side = lambda point: (x1-x0)*(point[1]-y0)-(y1-y0)*(point[0]-x0)
        if side(route[0]) * side(route[1]) >= 0:
            raise ValueError("original route does not cross governing stop line")
    except (TypeError, ValueError) as error:
        raise ValueError("invalid original route or stop-line geometry") from error
    return site


def construct(world, carla, site: dict, case: dict):
    """Spawn read-back bicycle and select an original governed signal/sign.

    Device authority and applicability are local source packets, never inferred
    from the CARLA actor label. Officer direction needs an independent local
    authority packet and a real actor/trace; absent support fails closed.
    """
    if site.get("map_name") != world.get_map().name:
        raise ValueError("Native map identity mismatch")
    if site["device_type"] != case["device_type"]:
        raise ValueError("case device type differs from source site")
    if case.get("officer_direction", "none") not in VALID_DIRECTIONS:
        raise ValueError("unsupported officer direction")
    if case.get("officer_direction", "none") != "none" and not site.get("police_authority_source"):
        raise ValueError("missing original Police Officer authority source")
    controls = {str(x.id): x for x in world.get_actors()}
    device = controls.get(site["device_id"])
    if device is None or not getattr(device, "is_alive", False):
        raise ValueError("governing Native device unavailable")
    library = world.get_blueprint_library()
    blueprint = library.find(site["bike_blueprint_id"])
    if blueprint is None or blueprint.id != site["bike_blueprint_id"]:
        raise ValueError("bicycle Native blueprint unavailable")
    origin = site["vehicle_route"][0]
    transform = carla.Transform(carla.Location(x=float(origin[0]), y=float(origin[1]), z=float(origin[2])))
    bike = world.spawn_actor(blueprint, transform)
    if bike is None:
        raise RuntimeError("bicycle spawn failed")
    try:
        if bike.type_id != site["bike_blueprint_id"] or not bike.is_alive:
            raise ValueError("bicycle Native actor readback mismatch")
        if bike.get_transform().location.distance(transform.location) > 1.0:
            raise ValueError("bicycle spawn location readback mismatch")
        return {"bike": bike, "device": device, "owned_actors": [bike], "route": site["vehicle_route"]}
    except BaseException:
        bike.destroy()
        raise


def audit_original_history(case: dict, site: dict, samples: list[dict]) -> dict:
    """Validate source-bound 20 Hz event sequence; report facts, no legal label."""
    if len(samples) < 2 or any(s.get("source_kind") != "original_native" for s in samples):
        raise ValueError("missing original Native samples")
    required = ("frame", "time_s", "bike_id", "bike_blueprint_id", "device_id", "device_state", "bike_front_xy", "officer_actor_id", "officer_command", "officer_authority_source")
    for i, s in enumerate(samples):
        if any(k not in s for k in required):
            raise ValueError("incomplete original Native sample")
        if s["bike_blueprint_id"] != site["bike_blueprint_id"] or s["device_id"] != site["device_id"]:
            raise ValueError("participant or device source mismatch")
        if i:
            prev = samples[i - 1]
            if s["frame"] != prev["frame"] + 1 or not 0.04 <= s["time_s"] - prev["time_s"] <= 0.06:
                raise ValueError("frame or 20 Hz time discontinuity")
            if s["bike_id"] != prev["bike_id"]:
                raise ValueError("bicycle actor identity changed")
        if case.get("officer_direction", "none") != "none":
            if not s["officer_actor_id"] or s["officer_authority_source"] != site.get("police_authority_source"):
                raise ValueError("Police Officer identity or authority not measured")
            if s["officer_command"] not in ("none", case["officer_direction"]):
                raise ValueError("officer command differs from case")
        elif s["officer_command"] != "none":
            raise ValueError("undeclared officer command")
    x0, y0 = map(float, site["stop_line"][0]); x1, y1 = map(float, site["stop_line"][1])
    def side(s):
        x, y = map(float, s["bike_front_xy"])
        return (x1-x0)*(y-y0)-(y1-y0)*(x-x0)
    sides = [side(s) for s in samples]
    crossing = next((i for i in range(1, len(sides)) if sides[i-1]*sides[i] < 0), None)
    return {"source_kind": "original_native", "case_id": case["case_id"], "bike_id": samples[0]["bike_id"], "device_id": site["device_id"], "crossing_frame": samples[crossing]["frame"] if crossing is not None else None, "device_state_at_crossing": samples[crossing]["device_state"] if crossing is not None else None, "officer_command_at_crossing": samples[crossing]["officer_command"] if crossing is not None else None, "legal_assessment": "unresolved"}

"""Lazy Native Police Officer actor and command source adapter.

The local operator must supply a reviewed authority packet and a visible gesture
asset. This code refuses a mere callback label as evidence of an officer command.
"""
from __future__ import annotations

import hashlib
import json
from pathlib import Path


RECIPIENT_ROLE = "selected_cycle_operator"


def route_digest(site: dict) -> str:
    return hashlib.sha256(json.dumps(site["vehicle_route"], sort_keys=True,
                                     separators=(",", ":")).encode()).hexdigest()


def read_officer_source(path: Path, expected_sha256: str, site: dict) -> dict:
    raw = path.read_bytes()
    if hashlib.sha256(raw).hexdigest() != expected_sha256:
        raise ValueError("original officer source hash mismatch")
    packet = json.loads(raw)
    required = ("source_kind", "map_name", "authority_source", "officer_blueprint_id",
                "gesture_asset_id", "spawn_xyz", "recipient_role",
                "recipient_route_sha256", "command",
                "start_frame", "end_frame", "visible_camera_ids")
    if any(k not in packet for k in required):
        raise ValueError("incomplete original officer source")
    if packet["source_kind"] != "original_local_officer_authority_and_gesture":
        raise ValueError("unverified original officer source")
    if packet["map_name"] != site["map_name"] or packet["authority_source"] != site.get("police_authority_source"):
        raise ValueError("officer map or authority source mismatch")
    if (packet["recipient_role"] != RECIPIENT_ROLE or
            packet["recipient_route_sha256"] != route_digest(site)):
        raise ValueError("officer recipient role or route source mismatch")
    if packet["command"] not in {"stop", "proceed"}:
        raise ValueError("unsupported original officer command")
    if not isinstance(packet["spawn_xyz"], list) or len(packet["spawn_xyz"]) != 3:
        raise ValueError("invalid officer spawn pose")
    if not isinstance(packet["start_frame"], int) or not isinstance(packet["end_frame"], int) or packet["start_frame"] >= packet["end_frame"]:
        raise ValueError("invalid officer command window")
    if len(set(packet["visible_camera_ids"])) < 2:
        raise ValueError("officer gesture has insufficient camera plan")
    return packet


def bind_recipient(packet: dict, bike, site: dict) -> dict:
    """Bind the reviewed role and route to the observed spawned actor id."""
    if (packet["recipient_role"] != RECIPIENT_ROLE or
            packet["recipient_route_sha256"] != route_digest(site) or
            not bike.is_alive or not str(bike.id)):
        raise ValueError("officer live recipient binding mismatch")
    bound = dict(packet)
    bound["observed_recipient_bike_id"] = str(bike.id)
    return bound


def construct(world, carla, packet: dict, case: dict, gesture_adapter) -> dict:
    """Spawn actor, read it back, and install a real gesture control adapter."""
    if case["officer_direction"] != packet["command"]:
        raise ValueError("officer command differs from exact case")
    if world.get_map().name != packet["map_name"]:
        raise ValueError("officer Native map readback mismatch")
    if not callable(gesture_adapter):
        raise ValueError("visible officer gesture adapter required")
    blueprint = world.get_blueprint_library().find(packet["officer_blueprint_id"])
    if blueprint is None or blueprint.id != packet["officer_blueprint_id"]:
        raise ValueError("officer blueprint unavailable")
    x, y, z = map(float, packet["spawn_xyz"])
    pose = carla.Transform(carla.Location(x=x, y=y, z=z))
    officer = world.spawn_actor(blueprint, pose)
    if officer is None:
        raise RuntimeError("officer actor spawn failed")
    try:
        if not officer.is_alive or officer.type_id != blueprint.id or officer.get_transform().location.distance(pose.location) > 1.0:
            raise ValueError("officer actor readback mismatch")
        gesture_adapter(officer, packet["gesture_asset_id"], packet["command"])
        return {"officer": officer, "owned_actors": [officer], "packet": packet}
    except BaseException:
        officer.destroy()
        raise


def read_command(officer, packet: dict, frame: int, gesture_reader, bike_id: str) -> dict:
    if not officer.is_alive or not callable(gesture_reader):
        raise ValueError("original officer actor or gesture reader unavailable")
    if str(bike_id) != packet.get("observed_recipient_bike_id"):
        raise ValueError("officer command recipient mismatch")
    active = packet["start_frame"] <= frame <= packet["end_frame"]
    observed = gesture_reader(officer, packet["gesture_asset_id"], frame)
    if active and observed != packet["command"]:
        raise ValueError("visible officer gesture readback missing")
    if not active and observed != "none":
        raise ValueError("officer gesture outside source window")
    return {"actor_id": str(officer.id), "authority_source": packet["authority_source"],
            "recipient_id": str(bike_id), "command": observed,
            "gesture_asset_id": packet["gesture_asset_id"], "frame": frame,
            "source_kind": "original_native_officer_readback"}

"""Native bicycle route actuation and source-bound readback, without legal labels."""
from __future__ import annotations
import math


def command_step(bike, carla, case: dict, site: dict, elapsed_s: float) -> dict:
    if not bike.is_alive or bike.type_id != site["bike_blueprint_id"]:
        raise ValueError("bicycle Native readback failed")
    route = site["vehicle_route"]
    if len(route) < 2:
        raise ValueError("route needs two source points")
    if case["operator_motion"] not in {"hold_before_stop_line", "cross_stop_line"}:
        raise ValueError("unknown operator movement")
    p0,p1=route[0],route[1]
    dx=float(p1[0])-float(p0[0]);dy=float(p1[1])-float(p0[1])
    norm=math.hypot(dx,dy)
    if norm < 1.0:
        raise ValueError("degenerate governed route")
    line = site.get("stop_line")
    if not isinstance(line, list) or len(line) != 2:
        raise ValueError("original stop line required for route actuation")
    x0, y0 = map(float, line[0]); x1, y1 = map(float, line[1])
    lx, ly = x1-x0, y1-y0
    line_length = math.hypot(lx, ly)
    if line_length < 0.1:
        raise ValueError("degenerate original stop line")
    def side(point):
        return lx*(float(point[1])-y0)-ly*(float(point[0])-x0)
    start_side, end_side = side(p0), side(p1)
    if start_side*end_side >= 0 or abs(start_side) < 0.1:
        raise ValueError("source route does not cross governed stop line")
    transform = bike.get_transform()
    extent = float(bike.bounding_box.extent.x)
    if not math.isfinite(extent) or extent <= 0:
        raise ValueError("bicycle front-body extent unavailable")
    forward = transform.get_forward_vector()
    front = (transform.location.x + forward.x*extent,
             transform.location.y + forward.y*extent)
    signed_distance_m = side(front)/line_length * (1 if start_side > 0 else -1)
    if not math.isfinite(signed_distance_m):
        raise ValueError("bicycle front-body position unavailable")
    if signed_distance_m < -0.05 and case["operator_motion"] == "hold_before_stop_line":
        raise ValueError("bicycle crossed stop line before hold")
    margin = float(site.get("engineering_hold_margin_m", 2.0))
    if not 0.5 <= margin <= 5.0:
        raise ValueError("unsafe engineering stop-line margin")
    speed=0.0 if case["operator_motion"]=="hold_before_stop_line" and signed_distance_m <= margin else float(site.get("engineering_target_speed_mps",3.0))
    if not 0.0 <= speed <= 8.0:
        raise ValueError("unsafe engineering speed")
    commanded=carla.Vector3D(x=dx/norm*speed,y=dy/norm*speed,z=0.0)
    bike.set_target_velocity(commanded)
    observed=bike.get_velocity()
    if not all(math.isfinite(v) for v in (observed.x,observed.y,observed.z)):
        raise ValueError("Native velocity readback unavailable")
    return {"source_kind":"original_native_control_readback","bike_id":str(bike.id),"elapsed_s":elapsed_s,"front_to_stop_line_m":signed_distance_m,"engineering_hold_margin_m":margin,"commanded_mps":[commanded.x,commanded.y,commanded.z],"observed_mps":[observed.x,observed.y,observed.z],"legal_assessment":"unresolved"}

"""Four original camera archives bound to each Native bicycle instruction tick."""
from __future__ import annotations

import hashlib
from io import BytesIO
from pathlib import Path
from zipfile import ZipFile, ZIP_STORED

from PIL import Image

CAMERAS = ('overview', 'approach', 'reference_corner', 'driver_reference')
DIMENSIONS = {'overview': (1920, 1080), 'approach': (1280, 720),
              'reference_corner': (1280, 720), 'driver_reference': (1280, 720)}


def sha_bytes(value):
    return hashlib.sha256(value).hexdigest()


class FourCameraCapture:
    def __init__(self, root, readers, dimensions=None):
        if set(readers) != set(CAMERAS):
            raise ValueError('four named original camera readers required')
        self.root = Path(root)
        self.dimensions = dimensions or DIMENSIONS
        if set(self.dimensions) != set(CAMERAS):
            raise ValueError('four named camera dimensions required')
        self.readers = readers
        self.archives = {}
        self.paths = {name: self.root / (name + '.png.zip') for name in CAMERAS}
        if any(path.exists() for path in self.paths.values()):
            raise ValueError('original camera archive already exists')
        self.root.mkdir(parents=True, exist_ok=True)
        try:
            for name, path in self.paths.items():
                self.archives[name] = ZipFile(path, 'x', compression=ZIP_STORED)
        except Exception:
            self.abort()
            raise
        self.count = 0

    def sample(self, row):
        frame = row['frame']
        if type(frame) is not int or frame < 0:
            raise ValueError('invalid original camera frame')
        bindings = {}
        for name in CAMERAS:
            sample = self.readers[name](frame)
            if not isinstance(sample, dict) or sample.get('frame') != frame:
                raise ValueError('original camera frame identity mismatch: ' + name)
            payload = sample.get('png_bytes')
            if not isinstance(payload, bytes) or not payload.startswith(b'\x89PNG\r\n\x1a\n'):
                raise ValueError('original camera PNG unavailable: ' + name)
            with Image.open(BytesIO(payload)) as image:
                image.verify()
            with Image.open(BytesIO(payload)) as image:
                if image.format != 'PNG' or image.size != tuple(self.dimensions[name]):
                    raise ValueError('original camera format or dimensions differ: ' + name)
                image.load()
            member = f'{frame:08d}.png'
            self.archives[name].writestr(member, payload)
            bindings[name] = {'member': member, 'sha256': sha_bytes(payload)}
        row['camera_frames'] = bindings
        self.count += 1

    def finish(self):
        for archive in self.archives.values():
            archive.close()
        self.archives.clear()
        return {name: {'path': path.name, 'sha256': sha_bytes(path.read_bytes()),
                       'frame_count': self.count, 'dimensions': list(self.dimensions[name])}
                for name, path in self.paths.items()}

    def abort(self):
        for archive in self.archives.values():
            archive.close()
        self.archives.clear()
        for path in self.paths.values():
            path.unlink(missing_ok=True)

"""Saved-only measurement of original bicycle, device, and officer history.

The input is an original Native packet sealed by its caller. Synthetic packets
exercise this checker but never establish a physical recording or legal result.
"""
from __future__ import annotations

import hashlib
import json
import math
from pathlib import Path

FORMAT = "c111329-native-instruction-trace"
FRAME_COUNT = 900
STOP_SPEED_MPS = 0.2  # Engineering measurement tolerance, not a legal cutoff.
DWELL_FRAMES = 20      # One-second observable hold window, not a legal minimum.


def measure(path: Path, expected_sha256: str, case: dict, site: dict, site_sha256: str) -> dict:
    raw = path.read_bytes()
    actual_sha256 = hashlib.sha256(raw).hexdigest()
    if actual_sha256 != expected_sha256:
        raise ValueError("original instruction trace hash mismatch")
    packet = json.loads(raw)
    if packet.get("format") != FORMAT or packet.get("source_kind") != "original_native":
        raise ValueError("unverified original Native instruction packet")
    if packet.get("case_id") != case["case_id"] or packet.get("site_sha256") != site_sha256:
        raise ValueError("case or site source binding mismatch")
    rows = packet.get("samples")
    if not isinstance(rows, list) or len(rows) != FRAME_COUNT:
        raise ValueError("incomplete original 20 Hz instruction history")
    required = {"frame", "time_s", "bike_id", "bike_blueprint_id", "device_id",
                "device_state", "bike_front_xy", "bike_speed_mps", "officer_actor_id",
                "officer_authority_source", "officer_recipient_id", "officer_command"}
    x0, y0 = map(float, site["stop_line"][0])
    x1, y1 = map(float, site["stop_line"][1])
    if math.hypot(x1 - x0, y1 - y0) < 0.1:
        raise ValueError("degenerate original stop line")
    route_start = site["vehicle_route"][0]
    start_side = (x1 - x0) * (float(route_start[1]) - y0) - (y1 - y0) * (float(route_start[0]) - x0)
    if abs(start_side) < 0.1:
        raise ValueError("route starts on original stop line")
    sides = []
    first = rows[0]
    for i, row in enumerate(rows):
        if not isinstance(row, dict) or not required.issubset(row):
            raise ValueError("missing original instruction sample source")
        if row["bike_id"] != first["bike_id"] or not row["bike_id"]:
            raise ValueError("bicycle identity changed")
        if row["bike_blueprint_id"] != site["bike_blueprint_id"] or row["device_id"] != site["device_id"]:
            raise ValueError("original participant or device identity mismatch")
        if row["device_state"] != case["device_instruction"]:
            raise ValueError("observed device instruction differs from case")
        if i:
            previous = rows[i - 1]
            if row["frame"] != previous["frame"] + 1 or not 0.04 <= row["time_s"] - previous["time_s"] <= 0.06:
                raise ValueError("original frame or 20 Hz clock discontinuity")
        speed = float(row["bike_speed_mps"])
        if not math.isfinite(speed) or speed < 0:
            raise ValueError("invalid original bicycle speed")
        xy = row["bike_front_xy"]
        if not isinstance(xy, list) or len(xy) != 2 or not all(math.isfinite(float(v)) for v in xy):
            raise ValueError("invalid original bicycle front position")
        side = (x1 - x0) * (float(xy[1]) - y0) - (y1 - y0) * (float(xy[0]) - x0)
        sides.append(side / abs(start_side))
        if case["officer_direction"] == "none":
            if row["officer_command"] != "none":
                raise ValueError("undeclared Police Officer command")
        else:
            if not row["officer_actor_id"] or row["officer_authority_source"] != site.get("police_authority_source"):
                raise ValueError("Police Officer identity or authority source missing")
            if row["officer_recipient_id"] != row["bike_id"]:
                raise ValueError("Police Officer command recipient mismatch")
            if row["officer_command"] not in {"none", case["officer_direction"]}:
                raise ValueError("Police Officer command differs from case")
    if sides[0] <= 0:
        raise ValueError("bicycle starts beyond governed stop line")
    crossing = next((i for i in range(1, len(sides)) if sides[i - 1] > 0 and sides[i] < 0), None)
    if case["operator_motion"] == "cross_stop_line":
        if crossing is None:
            raise ValueError("planned crossing absent from original history")
        event = crossing
    elif case["operator_motion"] == "hold_before_stop_line":
        if crossing is not None or min(sides) <= 0:
            raise ValueError("planned hold crossed original stop line")
        stationary = [i for i, row in enumerate(rows) if float(row["bike_speed_mps"]) <= STOP_SPEED_MPS and sides[i] > 0]
        if stationary[-DWELL_FRAMES:] != list(range(FRAME_COUNT - DWELL_FRAMES, FRAME_COUNT)):
            raise ValueError("planned hold lacks final observable dwell")
        event = FRAME_COUNT - DWELL_FRAMES
    else:
        raise ValueError("unknown planned bicycle movement")
    if case["officer_direction"] != "none":
        if any(row["officer_command"] != case["officer_direction"] for row in rows[max(0, event - DWELL_FRAMES): event + 1]):
            raise ValueError("Police Officer direction absent before response")
    return {
        "format": "c111329-saved-instruction-measurement",
        "source_kind": "original_native",
        "case_id": case["case_id"],
        "bike_id": first["bike_id"],
        "device_id": site["device_id"],
        "frame_count": FRAME_COUNT,
        "crossing_frame": rows[crossing]["frame"] if crossing is not None else None,
        "hold_window_frames": [rows[event]["frame"], rows[-1]["frame"]] if crossing is None else None,
        "device_state_at_response": rows[event]["device_state"],
        "officer_command_at_response": rows[event]["officer_command"],
        "source_hashes": {"site": site_sha256, "trace": actual_sha256},
        "legal_assessment": "unresolved",
    }

"""Saved-only bicycle instruction measurements from sealed original sources.

This report is descriptive. Device applicability, physical visibility, and legal
compliance are left to independent source and legal review.
"""
from __future__ import annotations

import argparse
import hashlib
import json
from pathlib import Path

from native_device import read_site
from saved_instruction import measure
from saved_camera_audit import audit as audit_cameras

SOURCES = ("original-site.json", "original-instruction-trace.json",
           "original-source-hashes.json")


def required(root: Path, name: str) -> Path:
    root = root.resolve()
    target = (root / name).resolve()
    if target.parent != root or not target.is_file():
        raise ValueError("Missing required source: " + name)
    return target


def sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def measure_device(instruction: dict) -> dict:
    return {"device_id": instruction["device_id"],
            "state_at_response": instruction["device_state_at_response"]}


def measure_actor(instruction: dict) -> dict:
    return {"bike_id": instruction["bike_id"], "device_id": instruction["device_id"]}


def measure_operator(instruction: dict) -> dict:
    return {"crossing_frame": instruction["crossing_frame"],
            "hold_window_frames": instruction["hold_window_frames"]}


def measure_officer(instruction: dict) -> dict:
    return {"command_at_response": instruction["officer_command_at_response"],
            "authority_and_recipient_verified": True}


def measure_media(camera: dict) -> dict:
    return {"decoded_frames": camera["decoded_frames"],
            "decoded_images": camera["decoded_images"]}


def finalize(root: Path, case: dict) -> dict:
    root = Path(root)
    paths = {name: required(root, name) for name in SOURCES}
    source_hashes = json.loads(paths["original-source-hashes.json"].read_text())
    if source_hashes.get("site") != sha(paths["original-site.json"]):
        raise ValueError("original site source manifest changed")
    diagnostic = required(root, "fixture-provenance.json") if (root / "fixture-provenance.json").is_file() else None
    site = read_site(paths["original-site.json"], source_hashes["site"],
                     allow_diagnostic=diagnostic is not None)
    if bool(site.get("diagnostic_fixture")) != (diagnostic is not None):
        raise ValueError("diagnostic site provenance mismatch")
    trace = paths["original-instruction-trace.json"]
    trace_hash = sha(trace)
    instruction = measure(trace, trace_hash, case, site, source_hashes["site"])
    if diagnostic is None:
        camera = audit_cameras(trace, trace_hash, case["case_id"])
    else:
        map_rows = required(root, "video_frames.jsonl").read_text().splitlines()
        if not map_rows:
            raise ValueError("diagnostic camera frame map missing")
        camera = {"decoded_frames": len(map_rows), "decoded_images": len(map_rows) * 4,
                  "diagnostic_fixture": True, "physical_acceptance": False}
    all_hashes = {name: sha(path) for name, path in paths.items()}
    outputs = (("observed_actor", measure_actor, instruction),
               ("observed_device_instruction", measure_device, instruction),
               ("observed_operator_response", measure_operator, instruction),
               ("observed_officer_direction", measure_officer, instruction),
               ("original_camera_decode", measure_media, camera))
    measurements = {key: {"method": method.__name__, "value": method(value),
                           "sources": all_hashes}
                    for key, method, value in outputs}
    return {"format": "worker-analysis-report", "case_id": case["case_id"],
            "measurements": measurements, "analysis_complete": True,
            "source_kind": "synthetic_fixture" if diagnostic else "original_native",
            "diagnostic_fixture": bool(diagnostic), "legal_assessment": "unresolved",
            "physical_acceptance": False}


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--attempt", required=True, type=Path)
    parser.add_argument("--output", required=True, type=Path)
    args = parser.parse_args()
    root = Path(__file__).resolve().parent
    config = json.loads((root / "config.json").read_text())
    plan = json.loads((root / "case-plan.json").read_text())
    cases = [row for row in plan["cases"] if row["case_id"] == config["selected_case_id"]]
    if len(cases) != 1:
        raise ValueError("exact selected case absent")
    result = finalize(args.attempt, cases[0])
    from worker_exchange.native_output import provenance_record, write_result
    attempt = args.attempt.resolve()
    description = config["case"]["recording_description"]
    instruction = json.loads(required(attempt, "original-instruction-trace.json").read_text())
    source_rows = {row["frame"]: row for row in instruction["samples"]}
    mapping = [json.loads(line) for line in required(attempt, "video_frames.jsonl").read_text().splitlines()]
    if not mapping or any(row["carla_frame"] not in source_rows for row in mapping):
        raise ValueError("original instruction and video frame map do not join")
    evidence = []
    for channel in description["channels"]:
        name = channel["name"]
        relative = "instruction-" + name + ".jsonl"
        with (attempt / relative).open("x") as stream:
            for frame in mapping:
                sample = source_rows[frame["carla_frame"]]
                if name == "bicycle_front_body_position":
                    value = sample["bike_front_xy"]
                elif name == "bicycle_speed":
                    value = sample["bike_speed_mps"]
                elif name == "device_instruction":
                    value = sample["device_state"]
                else:
                    value = {"officer_id": sample["officer_actor_id"],
                             "command": sample["officer_command"]}
                stream.write(json.dumps({"time_s": frame["time_s"], "value": value}) + "\n")
        evidence.append({"name": name, "unit": channel["unit"], "reference": relative})
    for context in description["context_inputs"]:
        reference = "context-" + context["name"] + ".json"
        value = {"source_sha256": sha(required(attempt, "original-site.json")),
                 "source_kind": "diagnostic_fixture" if result["diagnostic_fixture"] else "original_native"}
        if context["name"] == "reviewed_officer":
            value["officer_source_sha256"] = json.loads(
                required(attempt, "original-source-hashes.json").read_text()).get("officer")
        (attempt / reference).write_text(json.dumps({context["name"]: value}, sort_keys=True) + "\n")
        evidence.append({"name": context["name"], "unit": context["unit"],
                         "reference": reference})
    native_result = {
        "case_id": cases[0]["case_id"],
        "measured_values": {key: row["value"] for key, row in result["measurements"].items()},
        "target_checks": [{"target": "source_bound_instruction_response",
                           "requested": cases[0]["operator_motion"],
                           "measured": result["measurements"]["observed_operator_response"]["value"],
                           "method": "900-frame original bicycle front-body and speed history",
                           "tolerance": "engineering motion observation only", "matched": True,
                           "physical_cause_confirmed": False,
                           "cause_evidence": "Original site and trace are required; legal conclusion remains open"}],
        "setup_confirmed": False, "behavior_attempted": False,
        "maneuver_completed": False,
        "termination_reason": "saved-only instruction measurement; physical review pending",
        "physical_failure_flags": ["physical_completion_unverified"],
        "trace_reference": "trace.jsonl",
        "video_references": [name + ".mkv" for name in ("overview", "approach", "reference_corner", "driver_reference")],
        "video_frame_map_reference": "video_frames.jsonl",
        "recording_description": description,
        "recording_evidence": evidence,
        "realized_observables": {},
        **provenance_record(attempt),
        "physical_acceptance_claimed": False,
        "legal_verdict_claimed": False,
    }
    write_result(attempt, native_result)
    if args.output.exists():
        raise ValueError("saved analysis output already exists")
    args.output.write_text(json.dumps(result, indent=2, sort_keys=True) + "\n")


if __name__ == "__main__":
    main()
